INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(72648577, 'D/D/D Human Resources', 'DDD的人事权', 'DDDの人事権', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上·墓地的「DD」怪兽以及自己的灵摆区域的「DD」卡之中选合计3张回到持有者卡组。那之后，可以从卡组把2只「DD」怪兽加入手卡。'),
(71612253, 'D/D/D Marksman King Tell', 'DDD 狙击王退尔', 'DDD狙撃王テル', 'XYZ Monster', 'Fiend', 'DARK', 5, 2300, 2000, '5星怪兽×2 这张卡也能在自己场上的4阶「DDD」超量怪兽上面重叠来超量召唤。 ①：自己受到效果伤害的自己·对方回合1次，把这张卡1个超量素材取除，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力下降1000，给与对方1000伤害。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把1张「DD」卡或「契约书」卡送去墓地。'),
(74069667, 'D/D/D Oblivion King Abyss Ragnarok', 'DDD 坏薙王邃渊诸神黄昏', 'DDD壊薙王アビス・ラグナロク', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, 2200, 3000, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，以自己墓地1只「DDD」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：1回合1次，把自己场上1只其他的「DD」怪兽解放，以对方场上1只怪兽为对象才能发动。那只怪兽除外。'),
(82956492, 'D/D/D Oracle King d''Arc', 'DDD 神讬王达尔克', 'DDD神託王ダルク', 'Fusion Monster', 'Fiend', 'DARK', 7, 2800, 2000, '「DD」怪兽×2 ①：只要这张卡在怪兽区域存在，给与自己伤害的效果变成让自己基本分回复的效果。'),
(92536468, 'D/D/D Rebel King Leonidas', 'DDD 反骨王雷奥尼达', 'DDD反骨王レオニダス', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, 2600, 1200, '①：自己受到效果伤害时才能发动。这张卡从手卡特殊召唤，自己基本分回复受到的伤害的数值。 ②：只要这张卡在怪兽区域存在，自己受到的效果伤害变成0。'),
(30998403, 'D/D/D Sky King Zeus Ragnarok', 'DDD 天空王宙斯诸神黄昏', 'DDD天空王ゼウス・ラグナロク', 'Link Monster', 'Fiend', 'DARK', NULL, 2200, NULL, '「DD」怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1张「DD」卡或「契约书」卡为对象才能发动。那张卡破坏。这个回合，自己在通常的灵摆召唤外加上只有1次，自己主要阶段可以把「DD」怪兽灵摆召唤。 ②：对方把手卡的怪兽的效果发动时，从自己墓地把1只「DD」怪兽和1张「契约书」卡除外才能发动。那个发动无效。'),
(51497409, 'D/D/D Stone King Darius', 'DDD 磐石王大流士', 'DDD磐石王ダリウス', 'XYZ Monster', 'Fiend', 'EARTH', 3, 1900, 1000, '恶魔族3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己场上1张「契约书」卡为对象才能发动。那张卡破坏，自己从卡组抽1张。这个效果在对方回合也能发动。 ②：这张卡和对方怪兽进行战斗的伤害计算时，把这张卡1个超量素材取除才能发动。这张卡不会被那次战斗破坏，伤害计算后那只对方怪兽破坏，给与对方500伤害。'),
(72402069, 'D/D/D Super Doom King Bright Armageddon', 'DDD 超死伟王纯白地狱末日', 'DDD超死偉王ホワイテスト・ヘル・アーマゲドン', 'Synchro Pendulum Effect Monster', 'Fiend', 'DARK', 10, 3500, 3000, '「DD」调整＋调整以外的「DDD」怪兽1只以上 ①：只要这张卡在怪兽区域存在，对方不能把自己场上的怪兽作为效果的对象。 ②：这张卡已在怪兽区域存在的状态，这张卡以外的怪兽召唤·特殊召唤的场合才能发动。对方选自身场上1只灵摆怪兽。那只怪兽以外的对方场上的怪兽的效果无效化。 ③：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(18897163, 'D/D/D Super Doom King Dark Armageddon', 'DDD 超死伟王黯黑地狱末日', 'DDD超死偉王ダークネス・ヘル・アーマゲドン', 'XYZ Pendulum Effect Monster', 'Fiend', 'DARK', 8, 3500, 3000, '8星「DDD」怪兽×2 ①：这张卡超量召唤成功时才能发动。选自己的额外卡组1只表侧表示的「DD」灵摆怪兽在这张卡下面重叠作为超量素材。 ②：自己场上的灵摆怪兽不会被效果破坏。 ③：1回合1次，把这张卡1个超量素材取除，以自己场上的灵摆怪兽数量的对方场上的怪兽为对象才能发动。那些怪兽破坏。 ④：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(84569886, 'D/D/D Super Doom King Purple Armageddon', 'DDD 超死伟王至紫地狱末日', 'DDD超死偉王パープリッシュ・ヘル・アーマゲドン', 'Pendulum Effect Fusion Monster', 'Fiend', 'DARK', 10, 3500, 3000, '「DDD」怪兽×2 这个卡名的①的怪兽效果1回合只能使用1次。 ①：以对方场上1只攻击表示怪兽为对象才能发动。那只怪兽破坏，给与对方破坏的怪兽的原本攻击力一半数值的伤害。 ②：对方怪兽进行战斗的伤害计算前才能发动。那只对方怪兽的攻击力直到伤害步骤结束时变成原本数值。 ③：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(76029419, 'D/D/D Supersight King Zero Maxwell', 'DDD 超视王零麦克斯韦', 'DDD超視王ゼロ・マクスウェル', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, 2800, 2500, '①：这张卡向对方的守备表示怪兽攻击的伤害计算前才能发动。那只对方怪兽的守备力直到伤害步骤结束时变成0。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡的战斗发生的对自己的战斗伤害变成0。'),
(44186624, 'D/D/D Supreme King Kaiser', 'DDD 制霸王 皇帝', 'DDD制覇王カイゼル', 'Effect Monster', 'Fiend', 'DARK', 7, 2800, 2100, '①：这张卡灵摆召唤成功的场合发动。对方场上的表侧表示的卡的效果直到回合结束时无效。 ②：这张卡灵摆召唤成功的回合的主要阶段1次，以自己的魔法与陷阱区域最多2张卡为对象才能发动。那些卡破坏。这个回合，这张卡在同1次的战斗阶段中在通常攻击外加上可以作出最多有这个效果破坏的卡数量的攻击。'),
(25857977, 'D/D/D Vice King Requiem', 'DDD 死讴王恶德镇魂曲', 'DDD死謳王バイス・レクイエム', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, 2800, 2000, '这个卡名的②的怪兽效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己不是「DDD」怪兽不能特殊召唤。 ②：场上的这张卡为素材作融合·同调·超量·连接召唤的「DDD」怪兽得到以下效果。 ●1回合1次，以场上1张卡为对象才能发动。从自己的场上（表侧表示）·墓地让1张「契约书」卡回到卡组，作为对象的卡破坏。那之后，自己回复1000基本分。'),
(79559912, 'D/D/D Wave High King Caesar', 'DDD 怒涛大王执行凯撒', 'DDD怒涛大王エグゼクティブ・シーザー', 'XYZ Monster', 'Fiend', 'WATER', 6, 2800, 1800, '恶魔族6星怪兽×2 ①：包含把怪兽特殊召唤效果的怪兽的效果·魔法·陷阱卡发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。那之后，可以让这张卡和自己场上1只「DD」怪兽的攻击力直到回合结束时上升1800。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把1张「契约书」卡加入手卡。'),
(3758046, 'D/D/D Wave King Caesar', 'DDD 怒涛王凯撒', 'DDD怒濤王シーザー', 'XYZ Monster', 'Fiend', 'WATER', 4, 2400, 1200, '恶魔族4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡1个超量素材取除才能发动。这个回合的战斗阶段结束时，这个回合被破坏的怪兽从自己墓地尽可能特殊召唤。下个回合的准备阶段，自己受到这个效果特殊召唤的怪兽数量×1000伤害。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把1张「契约书」卡加入手卡。'),
(27873305, 'D/D/D Wave Oblivion King Caesar Ragnarok', 'DDD 怒涛坏薙王凯撒诸神黄昏', 'DDD怒濤壊薙王カエサル・ラグナロク', 'Fusion Monster', 'Fiend', 'DARK', 10, 3200, 3000, '「DDD」怪兽×2 ①：1回合1次，这张卡进行战斗的攻击宣言时，以自己场上的其他的1张「DD」卡或「契约书」卡为对象才能发动。那张卡回到手卡，和这张卡进行战斗的怪兽以外的对方场上1只表侧表示怪兽当作装备魔法卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。'),
(32232538, 'D/D/D Wise King Solomon', 'DDD 智慧王索罗门', 'DDD智慧王ソロモン', 'XYZ Monster', 'Fiend', 'DARK', 4, 1800, 2500, '4星「DD」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组把1张「DD」卡加入手卡。 ②：这张卡被除外的场合，以自己场上1只「DD」效果怪兽为对象才能发动。那只效果怪兽直到回合结束时得到以下效果。 ●这张卡战斗破坏怪兽的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(20715411, 'D/D/D Zero Doom Queen Machinex', 'DDD 零死王零降神', 'DDD零死王ゼロ・マキナ', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, 3000, NULL, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡在额外卡组表侧存在的状态，「DDD 零死王 零·机降神」以外的自己场上的表侧表示的「DDD」卡或「契约书」卡被破坏的场合才能发动（伤害步骤也能发动）。这张卡特殊召唤。那之后，可以把场上1张卡破坏。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(71398055, 'D/D/D/D Dimensional King Arc Crisis', 'DDDD 伟次元王巨弧危机', 'DDDD偉次元王アーク・クライシス', 'Pendulum Effect Fusion Monster', 'Fiend', 'DARK', 12, 4000, 4000, '恶魔族的融合·同调·超量·灵摆怪兽各1只合计4只 「DDDD 伟次元王 弧线危机神」1回合1次用融合召唤以及以下方法才能特殊召唤。 ●把自己的场上·墓地的上记的卡除外的场合可以从额外卡组（里侧）特殊召唤。 ①：这张卡特殊召唤的场合才能发动。对方场上的全部表侧表示怪兽的效果无效化。 ②：这张卡可以向对方怪兽全部各作1次攻击。 ③：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(97417863, 'D/D/D/D Super-Dimensional Sovereign Emperor Zero Paradox', 'DDDD 超次元统皇零悖论', 'DDDD超次元統皇ゼロ・パラドックス', 'Pendulum Effect Monster', 'Fiend', 'DARK', 12, 3000, 3000, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。 ①：自己把怪兽灵摆召唤时，若自己的灵摆区域的灵摆刻度合计超过灵摆召唤的怪兽的等级合计则能发动。这张卡从手卡特殊召唤，场上的其他卡全部破坏。那之后，可以把这张卡在自己的灵摆区域放置。 ②：1回合1次，自己场上的其他的表侧表示的「DDD」怪兽因魔法卡的效果从场上离开的场合发动。这张卡的攻击力变成6000。'),
(71249758, 'D2 Shield', 'D2护盾', 'D２シールド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧守备表示存在的1只怪兽发动。选择的怪兽的守备力变成原本守备力2倍的数值。'),
(50696588, 'Dai Dance', '粗人舞导', 'GUYダンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的效果在决斗中只能适用1次。 ①：指定没有使用的对方的主要怪兽区域1处才能发动。只要指定的区域是可以使用，对方要在主要怪兽区域把怪兽通常召唤·特殊召唤的场合，不是那个区域不能使用。这个效果直到指定的区域有怪兽被放置为止适用。'),
(41090784, 'Dai-sojo of the Ice Barrier', '冰结界的大僧正', '氷結界の大僧正', 'Effect Monster', 'Spellcaster', 'WATER', 6, 1600, 2200, '①：这张卡召唤·反转召唤的场合发动。这张卡变成守备表示。 ②：只要这张卡在怪兽区域存在，自己场上的「冰结界」怪兽不会被魔法·陷阱卡的效果破坏。'),
(69133798, 'Daidara-Bocchi', '大太郎法师', 'ダイダラボッチ', 'Effect Monster', 'Zombie', 'EARTH', 10, 2900, 2500, '这张卡不能特殊召唤。这张卡可以把1只不死族怪兽解放表侧表示上级召唤。 ①：这张卡的攻击力上升自己场上的其他的不死族怪兽数量×200。 ②：这张卡在墓地存在，自己墓地有「大太郎法师」以外的不死族怪兽2只以上存在的场合，自己主要阶段1开始时，丢弃1张手卡才能发动。这张卡加入手卡。'),
(39943352, 'Daidaratant the Ooze Giant', '液状巨人 大太胀流', '液状巨人ダイダラタント', 'XYZ Pendulum Effect Monster', 'Zombie', 'WATER', 4, 2400, 400, '4星怪兽×2 4星可以灵摆召唤的场合在额外卡组的表侧表示的这张卡可以灵摆召唤。这个卡名的①②的怪兽效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。这张卡在自己的灵摆区域放置。那之后，可以从自己墓地选1只灵摆怪兽表侧表示加入额外卡组。 ②：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(10755984, 'Daigusto Eguls', '大薰风天鹰', 'ダイガスタ・イグルス', 'Synchro Monster', 'Psychic', 'WIND', 7, 2600, 1800, '调整＋调整以外的名字带有「薰风」的怪兽1只以上 1回合1次，自己的结束阶段时可以从自己墓地把1只风属性怪兽从游戏中除外，选择对方场上里侧表示存在的1张卡破坏。'),
(581014, 'Daigusto Emeral', '大薰风翠玉', 'ダイガスタ・エメラル', 'XYZ Monster', 'Rock', 'WIND', 4, 1800, 800, '4星怪兽×2 ①：1回合1次，可以把这张卡1个超量素材取除，从以下效果选择1个发动。 ●以自己墓地3只怪兽为对象才能发动。那3只怪兽加入卡组洗切。那之后，自己从卡组抽1张。 ●以效果怪兽以外的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(34109611, 'Daigusto Falcos', '大薰风飞隼', 'ダイガスタ・ファルコス', 'Synchro Monster', 'Psychic', 'WIND', 4, 1400, 1200, '调整＋调整以外的名字带有「薰风」的怪兽1只以上 这张卡同调召唤成功时，场上表侧表示存在的名字带有「薰风」的全部怪兽的攻击力上升600。'),
(84766279, 'Daigusto Gulldos', '大薰风翔鹏', 'ダイガスタ・ガルドス', 'Synchro Monster', 'Psychic', 'WIND', 5, 2200, 800, '调整＋调整以外的名字带有「薰风」的怪兽1只以上 1回合1次，可以让自己墓地存在的2只名字带有「薰风」的怪兽回到卡组，选择对方场上表侧表示存在的1只怪兽破坏。'),
(76937326, 'Daigusto Laplampilica', '大薰风兽使 翼心皮莉佳', 'ダイガスタ・ラプラムピリカ', 'Synchro Monster', 'Psychic', 'WIND', 6, 1900, 2600, '调整＋调整以外的「薰风」怪兽1只以上 自己对「大薰风兽使 翼心皮莉佳」1回合只能有1次特殊召唤。 ①：这张卡同调召唤成功的场合才能发动。「薰风」怪兽从手卡以及卡组各1只效果无效特殊召唤，只用那2只为素材把1只「薰风」同调怪兽同调召唤。这个回合，自己不是风属性怪兽不能特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的其他的「薰风」同调怪兽不会成为对方的效果的对象。'),
(2766877, 'Daigusto Phoenix', '大薰风凤凰', 'ダイガスタ・フェニクス', 'XYZ Monster', 'Pyro', 'WIND', 2, 1500, 1100, '2星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择自己场上表侧表示存在的1只风属性怪兽才能发动。这个回合，选择的怪兽在同1次的战斗阶段中可以作2次攻击。'),
(29552709, 'Daigusto Sphreez', '大薰风的球风', 'ダイガスタ・スフィアード', 'Synchro Monster', 'Psychic', 'WIND', 6, 2000, 1300, '调整＋调整以外的「薰风」怪兽1只以上 ①：这张卡同调召唤成功时，以自己墓地1张「薰风」卡为对象才能发动。那张卡加入手卡。 ②：这张卡不会被战斗破坏。 ③：只要这张卡在怪兽区域存在，自己的「薰风」怪兽的战斗发生的对自己的战斗伤害由对方代受。'),
(42542842, 'Dakki, the Graceful Mayakashi', '丽之魔妖－妲姬', '麗の魔妖－妲姫', 'Tuner Monster', 'Zombie', 'FIRE', 2, 1000, NULL, '①：「丽之魔妖-妲姬」在自己场上只能有1只表侧表示存在。 ②：这张卡在墓地存在，「魔妖」怪兽从额外卡组往自己场上特殊召唤时才能发动。这张卡特殊召唤。这个效果发动的回合，自己不是「魔妖」怪兽不能从额外卡组特殊召唤。'),
(44584775, 'Damage = Reptile', '伤害=爬虫', 'ダメージ＝レプトル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，爬虫类族怪兽的战斗让自己受到战斗伤害时才能发动。把持有那个时候受到的伤害数值以下的攻击力的1只爬虫类族怪兽从卡组特殊召唤。'),
(28378427, 'Damage Condenser', '伤害电容器', 'ダメージ・コンデンサー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己受到战斗伤害时，丢弃1张手卡才能发动。持有那个时候受到的伤害数值以下的攻击力的1只怪兽从卡组攻击表示特殊召唤。'),
(95448692, 'Damage Diet', '伤害瘦身', 'ダメージ・ダイエット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个回合自己受到的全部伤害变成一半。此外，可以把墓地存在的这张卡从游戏中除外，那个回合自己受到的效果伤害变成一半。'),
(60741115, 'Damage Eater', '伤害吞噬者', 'ダメージ・イーター', 'Effect Monster', 'Fiend', 'DARK', 2, 100, 800, '对方把给与伤害的魔法·陷阱·效果怪兽的效果发动时，把墓地存在的这张卡从游戏中除外才能发动。那个效果变成基本分回复效果。这个效果在对方回合才能发动。'),
(87106146, 'Damage Gate', '伤害之门', 'ダメージ・ゲート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己受到战斗伤害时才能发动。把持有那个时候受到的伤害数值以下的攻击力的1只怪兽从自己墓地往场上特殊召唤。'),
(50613779, 'Damage Mage', '伤害法师', 'ダメージ・メイジ', 'Effect Monster', 'Spellcaster', 'DARK', 3, 600, 1200, '卡的效果让自己受到伤害时才能发动。这张卡从手卡特殊召唤，自己基本分回复受到的伤害的数值。'),
(46031686, 'Damage Polarizer', '伤害偏光盾', 'ダメージ・ポラリライザー', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '给与伤害的效果发动时才能发动。那个发动和效果无效，双方玩家抽1张卡。'),
(35268887, 'Damage Translation', '伤害转化', 'ダメージ・トランスレーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个回合自己受到的效果伤害变成一半数值。这个回合的结束阶段时，和受到的效果伤害次数相同数量在自己场上把「幽灵衍生物」（恶魔族·暗·1星·攻/守0）守备表示特殊召唤。'),
(98535702, 'Damage Vaccine Omega MAX', '伤害疫苗ΩMAX', 'ダメージ・ワクチンΩMAX', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己因战斗或者卡的效果受到伤害时才能发动。自己基本分回复自己受到的那次伤害的数值。'),
(59546528, 'Dance Princess of the Ice Barrier', '冰结界的舞姬', '氷結界の舞姫', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1700, 900, '①：1回合1次，自己场上有其他的「冰结界」怪兽存在的场合，把手卡的「冰结界」怪兽任意数量给对方观看，以那个数量的对方场上的里侧表示的魔法·陷阱卡为对象才能发动。那些里侧表示卡回到手卡。'),
(52738610, 'Dance Princess of the Nekroz', '影灵衣的舞姬', '影霊衣の舞姫', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1600, 800, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，对方不能对应「影灵衣」仪式魔法卡的发动把魔法·陷阱·怪兽的效果发动，对方不能把自己场上的「影灵衣」仪式怪兽作为效果的对象。 ②：这张卡被效果解放的场合，以「影灵衣舞姬」以外的自己的除外状态的1只「影灵衣」怪兽为对象才能发动。那只怪兽加入手卡。'),
(33298291, 'Dances with Beasts', '兽血奔腾', '獣湧き肉躍り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方怪兽的直接攻击宣言时，对方场上的表侧表示怪兽的攻击力合计是8000以上的场合才能发动。把3只原本卡名不同的怪兽从自己的手卡·卡组·墓地各选1只攻击表示特殊召唤。'),
(59983499, 'Dancing Elf', '舞动精灵', 'ダンシング・エルフ', 'Normal Monster', 'Fairy', 'WIND', 1, 300, 200, '配合音乐飞天起舞的精灵。身体的羽毛是锐利的刀具。'),
(90925163, 'Dancing Fairy', '舞蹈妖精', '踊る妖精', 'Effect Monster', 'Fairy', 'WIND', 4, 1700, 1000, '只要这张卡在自己场上表侧守备表示存在，每次自己的准备阶段回复1000基本分。'),
(36629635, 'Dandy Whitelion', '蒲公英白狮', 'ダンディ・ホワイトライオン', 'Effect Monster', 'Plant', 'EARTH', 3, 300, 300, '这个卡名的效果1回合只能使用1次，这个效果发动的回合，自己不能从额外卡组把怪兽特殊召唤。 ①：这张卡从手卡·场上送去墓地的场合才能发动。在自己场上把3只「白绵毛衍生物」（植物族·风·1星·攻/守0）守备表示特殊召唤。'),
(15341821, 'Dandylion', '蒲公英狮', 'ダンディライオン', 'Effect Monster', 'Plant', 'EARTH', 3, 300, 300, '①：这张卡被送去墓地的场合发动。在自己场上把2只「绵毛衍生物」（植物族·风·1星·攻/守0）守备表示特殊召唤。这衍生物在特殊召唤的回合不能为上级召唤而解放。'),
(43316238, 'Danger! Bigfoot!', '未界域之大脚', '未界域のビッグフット', 'Effect Monster', 'Beast', 'DARK', 8, 3000, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的大脚怪」以外的场合，再从手卡把1只「未界域的大脚怪」特殊召唤，自己抽1张。 ②：这张卡从手卡丢弃的场合，以对方场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(16209941, 'Danger! Chupacabra!', '未界域之卓柏卡布拉', '未界域のチュパカブラ', 'Effect Monster', 'Fiend', 'DARK', 4, 1500, 400, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的卓柏卡布拉」以外的场合，再从手卡把1只「未界域的卓柏卡布拉」特殊召唤，自己抽1张。 ②：这张卡从手卡丢弃的场合，以「未界域的卓柏卡布拉」以外的自己墓地1只「未界域」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(23213239, 'Danger! Disturbance! Disorder!', '激荡之未界域', '激動の未界域', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己的「未界域」怪兽被和对方怪兽的战斗破坏时才能发动。那只对方怪兽破坏。 ②：从自己墓地把「未界域」魔法·陷阱卡3种类各1张除外才能发动。场上的卡全部破坏。这个效果的发动后，直到回合结束时自己不是「未界域」怪兽不能特殊召唤。'),
(26302107, 'Danger! Dogman!', '未界域之狼人', '未界域のワーウルフ', 'Effect Monster', 'Beast-Warrior', 'DARK', 7, 2400, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的狼人」以外的场合，再从手卡把1只「未界域的狼人」特殊召唤，自己从卡组抽1张。 ②：这张卡从手卡丢弃的场合才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降1000。'),
(57433966, 'Danger! Excitement! Mystery!', '魅惑的未界域', '魅惑の未界域', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡丢弃1只5星以上的「未界域」怪兽才能发动。从卡组把1只4星以下的「未界域」怪兽加入手卡。这张卡的发动后，直到回合结束时自己不是「未界域」怪兽不能特殊召唤。'),
(83928661, 'Danger! Feets of Strength!', '未界域捕缚作战', '未界域捕縛作戦', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「未界域」怪兽才能装备。 ①：装备怪兽的攻击力·守备力上升800，不会被效果破坏。 ②：装备怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(52350806, 'Danger! Mothman!', '未界域之飞蛾人', '未界域のモスマン', 'Effect Monster', 'Insect', 'DARK', 4, 1800, 400, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的天蛾人」以外的场合，再从手卡把1只「未界域的天蛾人」特殊召唤，自己从卡组抽1张。 ②：这张卡从手卡丢弃的场合才能发动。双方各自从卡组抽1张。那之后，抽卡的玩家选自身1张手卡丢弃。'),
(70711847, 'Danger! Nessie!', '未界域之尼斯湖水怪', '未界域のネッシー', 'Effect Monster', 'Aqua', 'DARK', 7, 1600, 2800, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的尼斯水怪」以外的场合，再从手卡把1只「未界域的尼斯水怪」特殊召唤，自己抽1张。 ②：这张卡从手卡丢弃的场合才能发动。从卡组把「未界域的尼斯水怪」以外的1张「未界域」卡加入手卡。'),
(83518674, 'Danger! Ogopogo!', '未界域之欧戈波戈', '未界域のオゴポゴ', 'Effect Monster', 'Sea Serpent', 'DARK', 8, 1200, 3000, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的奥古布古」以外的场合，再从手卡把1只「未界域的奥古布古」特殊召唤，自己从卡组抽1张。 ②：这张卡从手卡丢弃的场合才能发动。从卡组把「未界域的奥古布古」以外的1张「未界域」卡送去墓地。'),
(25140659, 'Danger! Response Team', '未界域调查报告', '未界域調査報告', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「未界域」怪兽和场上1只怪兽为对象才能发动。那些怪兽回到持有者手卡。 ②：这张卡在墓地存在的场合，从手卡丢弃1只「未界域」怪兽才能发动。这张卡回到卡组最下面。那之后，自己从卡组抽1张。'),
(90807199, 'Danger! Thunderbird!', '未界域之雷鸟', '未界域のサンダーバード', 'Effect Monster', 'Winged Beast', 'DARK', 8, 2800, 2400, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的雷鸟」以外的场合，再从手卡把1只「未界域的雷鸟」特殊召唤，自己从卡组抽1张。 ②：这张卡从手卡丢弃的场合，以对方场上盖放的1张卡为对象才能发动。那张卡破坏。'),
(15083304, 'Danger! Zone', '未界域的危险地带', '未界域の危険地帯', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己从卡组抽3张。那之后，从手卡把包含「未界域」卡1张以上的2张卡丢弃。手卡没有「未界域」卡的场合，手卡全部公开，回到卡组。'),
(43694650, 'Danger!? Jackalope?', '未界域之鹿角兔', '未界域のジャッカロープ', 'Effect Monster', 'Beast', 'DARK', 3, 500, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的鹿角兔」以外的场合，再从手卡把1只「未界域的鹿角兔」特殊召唤，自己从卡组抽1张。 ②：这张卡从手卡丢弃的场合才能发动。从卡组把「未界域的鹿角兔」以外的1只「未界域」怪兽守备表示特殊召唤。'),
(99745551, 'Danger!? Tsuchinoko?', '未界域之土龙', '未界域のツチノコ', 'Effect Monster', 'Reptile', 'DARK', 3, 1300, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从自己的全部手卡之中由对方随机选1张，自己把那张卡丢弃。那是「未界域的槌子蛇」以外的场合，再从手卡把1只「未界域的槌子蛇」特殊召唤，自己从卡组抽1张。 ②：这张卡从手卡丢弃的场合才能发动。这张卡特殊召唤。'),
(58468105, 'Dangerous Frightfur Nightmary', '凶邪魔玩具·梦魇玛丽', 'デンジャラス・デストーイ・ナイトメアリー', 'Fusion Monster', 'Fiend', 'DARK', 10, 2000, 3000, '「锋利小鬼」怪兽＋「毛绒动物」怪兽×2 ①：这张卡的攻击力在自己回合内上升自己墓地的天使族·恶魔族怪兽数量×300。 ②：融合召唤的这张卡战斗破坏怪兽时才能发动。把那只怪兽的等级数量的「魔玩具」、「毛绒动物」、「锋利小鬼」怪兽从卡组送去墓地。 ③：场上的这张卡为对象的对方的效果发动时，从额外卡组把1只「魔玩具」怪兽除外才能发动。那个效果无效。'),
(76895648, 'Dangerous Machine Type-6', '危险机器 6型', 'デンジャラスマシン TYPE－６', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的准备阶段丢1个骰子，根据丢出的数目决定效果。 ●投掷1的场合：自己丢弃1张手卡。 ●投掷2的场合：对方丢弃1张手卡。 ●投掷3的场合：自己抽1张卡。 ●投掷4的场合：对方抽1张卡。 ●投掷5的场合：对方的场上1只怪兽破坏。 ●投掷6的场合：这张卡破坏。'),
(22082432, 'Dangers of the Divine', '神之怒', '神の怒り', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把基本分支付一半，把自己场上1只怪兽解放才能发动。自己的手卡·除外状态的1只「太阳神之翼神龙」无视召唤条件特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成4000，不能攻击，下个回合的结束阶段回到手卡。 ②：这张卡从场上送去墓地的场合发动。选自己场上1只「太阳神之翼神龙」，那只怪兽以外的场上的怪兽全部送去墓地。'),
(48588176, 'Danipon', '壁虱宝宝', 'ダニポン', 'Effect Monster', 'Insect', 'EARTH', 2, 600, 600, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1只守备力1000以下的昆虫族怪兽加入手卡。'),
(66192538, 'Danmari @Ignister', '沉默默＠伊格尼斯者', 'ダンマリ＠イグニスター', 'Effect Monster', 'Cyberse', 'DARK', 6, 2300, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的「@火灵天星」怪兽进行战斗的攻击宣言时才能发动。这张卡从手卡特殊召唤，那次攻击无效。 ②：自己场上有连接6怪兽存在的场合，把场上·墓地的这张卡除外，以对方场上1张表侧表示的卡为对象才能发动。那张卡的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(18386170, 'Dante, Pilgrim of the Burning Abyss', '彼岸巡礼者 但丁', '彼岸の巡礼者 ダンテ', 'Fusion Monster', 'Fairy', 'LIGHT', 9, 2800, 2500, '卡名不同的「彼岸」怪兽×3 这张卡不用融合召唤不能特殊召唤。 ①：这张卡不会成为对方的效果的对象。 ②：1回合1次，把手卡1张「彼岸」卡送去墓地才能发动。自己从卡组抽1张。这个效果在对方回合也能发动。 ③：场上的这张卡被对方的效果送去墓地的场合或者被战斗破坏送去墓地的场合才能发动。对方手卡随机选1张送去墓地。'),
(83531441, 'Dante, Traveler of the Burning Abyss', '彼岸旅人 但丁', '彼岸の旅人 ダンテ', 'XYZ Monster', 'Warrior', 'LIGHT', 3, 1000, 2500, '3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，从自己卡组上面把最多3张卡送去墓地才能发动。这张卡的攻击力直到回合结束时上升因为这个效果发动而送去墓地的卡数量×500。 ②：这张卡攻击的场合，战斗阶段结束时变成守备表示。 ③：这张卡被送去墓地的场合，以自己墓地1张其他的「彼岸」卡为对象才能发动。那张卡加入手卡。'),
(97001138, 'Dark Advance', '暗黑上级召唤', 'ダーク・アドバンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「暗黑上级召唤」在1回合只能发动1张。 ①：自己·对方的主要阶段以及战斗阶段，以自己墓地1只攻击力2400以上而守备力1000的怪兽为对象才能发动。那只怪兽加入手卡。那之后，可以从手卡把1只攻击力2400以上而守备力1000的怪兽表侧攻击表示上级召唤。'),
(34479658, 'Dark Alligator', '暗黑短吻鳄', 'ダーク・アリゲーター', 'Effect Monster', 'Reptile', 'DARK', 8, 2500, 2300, '这张卡可以把1只爬虫类族怪兽解放作上级召唤。 ①：这张卡上级召唤成功时才能发动。把最多有为这张卡的上级召唤而解放的爬虫类族怪兽数量的「短吻鳄衍生物」（爬虫类族·暗·1星·攻2000/守0）在自己场上特殊召唤。 ②：上级召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把「暗黑短吻鳄」以外的1只爬虫类族怪兽加入手卡。'),
(28593329, 'Dark Angel', '暗黑安琪儿', 'ダーク・エンジェル', 'Effect Monster', 'Fairy', 'DARK', 5, NULL, NULL, '①：自己的天使族怪兽被选择作为攻击对象时，把那只怪兽解放，把这张卡从手卡送去墓地，以自己场上1只表侧表示怪兽为对象才能发动。攻击对象转移为那只自己怪兽，作为对象的怪兽的攻击力直到回合结束时上升解放的天使族怪兽的原本攻击力数值。'),
(95685352, 'Dark Anthelion Dragon', '暗向日龙', 'ダーク・アンセリオン・ドラゴン', 'XYZ Pendulum Effect Monster', 'Dragon', 'DARK', 7, 3000, 2500, '7星怪兽×2 7星可以灵摆召唤的场合在额外卡组的表侧表示的这张卡可以灵摆召唤。 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只怪兽的攻击力变成一半，这张卡的攻击力上升那个数值。这个效果在对方回合也能发动。 ②：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(65192027, 'Dark Armed Dragon', '暗黑武装龙', 'ダーク・アームド・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, 2800, 1000, '这张卡不能通常召唤。自己墓地的暗属性怪兽是3只的场合才能特殊召唤。 ①：从自己墓地把1只暗属性怪兽除外，以场上1张卡为对象才能发动。那张卡破坏。'),
(78144171, 'Dark Armed, the Dragon of Annihilation', '击灭龙 暗黑武装', '撃滅龍 ダーク・アームド', 'XYZ Monster', 'Dragon', 'DARK', 7, 2800, 1000, '7星怪兽×2只以上 「击灭龙 暗黑武装」1回合1次也能在自己墓地的暗属性怪兽只有5只的场合，在自己场上的5星以上的龙族·暗属性怪兽上面重叠来超量召唤。 ①：把这张卡1个超量素材取除，以对方场上1张卡为对象才能发动。那张卡破坏。那之后，从自己墓地选1张卡除外。这个效果的发动后，直到回合结束时这张卡不能攻击。'),
(72520073, 'Dark Artist', '暗之艺术家', '闇の芸術家', 'Effect Monster', 'Fiend', 'DARK', 3, 600, 1400, '受到了光属性怪兽的攻击时，这张卡的守备力成为一半。'),
(41949033, 'Dark Assailant', '暗之暗杀者', '闇の暗殺者', 'Normal Monster', 'Zombie', 'DARK', 4, 1200, 1200, '持有精神之剑、君临魔界的暗杀者。'),
(80071763, 'Dark Balter the Terrible', '魔人 暗黑护持师', '魔人 ダーク・バルター', 'Fusion Monster', 'Fiend', 'DARK', 5, 2000, 1200, '「凭依的血魂」＋「边境的大贤者」 融合召唤这只怪兽，必须用上面所写的卡融合召唤。通常魔法发动时支付1000分，那个通常魔法的效果无效化。这张卡战斗破坏的效果怪兽的效果无效化。'),
(67049542, 'Dark Bat', '暗黑蝙蝠', 'ダークバット', 'Normal Monster', 'Winged Beast', 'WIND', 3, 1000, 1000, '住在暗世界用精神波动找寻敌人的蝙蝠。'),
(81034083, 'Dark Beckoning Beast', '暗黑招来神', '暗黒の招来神', 'Effect Monster', 'Fiend', 'DARK', 2, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤时才能发动。把「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中1只或者有那其中任意种的卡名记述的1张「暗黑之招来神」以外的卡从卡组加入手卡。 ②：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只攻击力和守备力是0的恶魔族怪兽召唤。'),
(11321183, 'Dark Blade', '暗魔界战士 暗黑剑', '闇魔界の戦士 ダークソード', 'Normal Monster', 'Warrior', 'DARK', 4, 1800, 1500, '据说会操纵龙的暗魔界的战士。邪恶之力所使出的挥斩攻击威力惊人。'),
(57784563, 'Dark Blade the Captain of the Evil World', '暗魔界的战士长 暗黑之剑', '闇魔界の戦士長 ダークソード', 'Effect Monster', 'Warrior', 'DARK', 4, 1800, 1500, '1回合1次，把自己墓地1只暗属性怪兽从游戏中除外，选择对方场上1只光属性·4星以下的怪兽才能发动。选择的怪兽当作装备卡使用只有1只给这张卡装备。此外，场上的这张卡被破坏的场合，作为代替把这张卡的效果装备的怪兽破坏。'),
(86805855, 'Dark Blade the Dragon Knight', '暗魔界的龙骑士 暗黑之剑', '闇魔界の竜騎士 ダークソード', 'Fusion Monster', 'Warrior', 'DARK', 6, 2200, 1500, '「暗魔界的战士 暗黑之剑」＋「漆黑的斗龙」 每次这张卡给与对方战斗伤害，可以选择对方的墓地的最多3张怪兽卡，从游戏中除外。'),
(77538567, 'Dark Bribe', '魔宫的贿赂', '魔宮の賄賂', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。对方抽1张。'),
(44341034, 'Dark Bug', '暗虫', 'ダーク・バグ', 'Effect Monster', 'Insect', 'DARK', 1, 100, 100, '这张卡召唤成功时，选择自己墓地存在的1只3星的调整在自己场上特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(49702428, 'Dark Burning Attack', '黑·魔·导·爆·裂·破', '黒・魔・導・爆・裂・破', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「黑魔术少女」怪兽存在的场合才能发动。对方场上的表侧表示怪兽全部破坏。'),
(75190122, 'Dark Burning Magic', '黑·爆·裂·破·魔·导', '黒・爆・裂・破・魔・導', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上有原本卡名是「黑魔术师」和「黑魔术少女」的怪兽存在的场合才能发动。对方场上的卡全部破坏。'),
(12071500, 'Dark Calling', '黑暗呼唤', 'ダーク・コーリング', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的手卡·墓地的怪兽作为融合素材除外，把「暗黑融合」的效果才能特殊召唤的1只融合怪兽当作「暗黑融合」的融合召唤作融合召唤。'),
(8634636, 'Dark Cat with White Tail', '白尾黑猫', '尾も白い黒猫', 'Flip Effect Monster', 'Beast', 'EARTH', 2, 800, 500, '反转：将对方场上2只怪兽与自己场上1只怪兽弹回持有者手卡。'),
(33875961, 'Dark Catapulter', '暗黑弹射手', 'ダーク・カタパルター', 'Effect Monster', 'Machine', 'EARTH', 4, 1000, 1500, '自己的准备阶段时这张卡守备表示的场合，这张卡放置1个指示物。可以从自己墓地除外和指示物同数量的卡，破坏场上和除外的卡片数同数量的魔法·陷阱卡。之后这张卡的指示物全部取除。'),
(73452089, 'Dark Cavalry', '超魔导骑士－黑骑兵', '超魔導騎士－ブラック・キャバルリー', 'Fusion Monster', 'Spellcaster', 'DARK', 8, 2800, 2300, '「黑魔术师」＋战士族怪兽 ①：这张卡的攻击力上升双方的场上·墓地的魔法·陷阱卡数量×100。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：场上的卡为对象的魔法·陷阱·怪兽的效果发动时，丢弃1张手卡才能发动。那个发动无效并破坏。'),
(32344688, 'Dark Chimera', '暗黑奇美拉', 'ダーク・キメラ', 'Normal Monster', 'Fiend', 'DARK', 5, 1610, 1460, '生息在魔界的怪兽。吐出暗炎攻击。'),
(53527835, 'Dark City', '暗黑都市', 'ダーク・シティ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：「命运英雄」怪兽向持有比那个攻击力高的攻击力的怪兽攻击的场合，攻击怪兽的攻击力只在伤害计算时上升1000。'),
(1804528, 'Dark Coffin', '诅咒之棺', '呪われた棺', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '盖放的这张卡被破坏送去墓地时，对方从以下的效果选择1个适用。 ●随机丢弃自己的1张手卡。 ●自己场上的1只怪兽破坏。'),
(77124096, 'Dark Contact', '黑暗接触', 'ダーク・コンタクト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己的场上·墓地·除外状态的怪兽作为融合素材回到卡组，把「暗黑融合」的效果才能特殊召唤的1只融合怪兽当作「暗黑融合」的融合召唤作融合召唤。 ●从卡组把1张「霸王城」或「暗黑融合」加入手卡。'),
(37209439, 'Dark Contract with Errors', '误封的契约书', '誤封の契約書', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己场上有「DD」怪兽存在的场合才能把这个效果发动。直到回合结束时，这张卡以外的场上的陷阱卡的效果无效化。 ②：自己准备阶段发动。自己受到1000伤害。'),
(33814281, 'Dark Contract with Patent License', '专利权的契约书文件', '特許権の契約書類', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：和自己场上的「DDD」怪兽相同种类（融合·同调·超量·连接）的怪兽由对方特殊召唤的场合才能发动。给与对方1000伤害。这个回合，这张卡在场上存在期间，对方不能把和那些特殊召唤的怪兽相同种类的怪兽特殊召唤。 ②：这张卡被送去墓地的场合才能发动。从自己墓地的怪兽以及自己的额外卡组的表侧表示的灵摆怪兽之中选1只「DD」怪兽加入手卡。'),
(54936778, 'Dark Contract with the Different Dimension', '异次元的契约书', '異次元の契約書', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：从自己墓地让2张「契约书」卡回到卡组，以对方的场上·墓地1张卡为对象才能发动。那张卡除外。 ②：自己准备阶段发动。自己受到1000伤害。 ③：这张卡被破坏的场合才能发动。自己回复500基本分。被对方的效果破坏的场合，再让自己回复500基本分。'),
(60168186, 'Dark Contract with the Entities', '异形神的契约书', '異形神の契約書', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上有以下种类的「DDD」怪兽从额外卡组特殊召唤时，各自效果1回合各能发动1次。 ●融合：自己回复1000基本分。 ●同调：特殊召唤的那些怪兽不会成为对方的效果的对象。 ●超量：选自己或者对方的场上·墓地1张卡除外。 ●灵摆：自己从卡组抽1张，那之后选1张手卡丢弃。 ②：自己准备阶段发动。自己受到2000伤害。'),
(9030160, 'Dark Contract with the Eternal Darkness', '常暗的契约书', '常闇の契約書', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己的灵摆区域有2张「DD」卡存在的场合，对方不能把场上的怪兽作为魔法·陷阱卡的效果的对象，不能作为上级召唤的解放，也不能作为融合·同调·超量召唤的素材。 ②：自己准备阶段发动。自己受到1000伤害。'),
(46372010, 'Dark Contract with the Gate', '地狱门的契约书', '地獄門の契約書', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从卡组把1只「DD」怪兽加入手卡。 ②：自己准备阶段发动。自己受到1000伤害。'),
(73360025, 'Dark Contract with the Swamp King', '魔神王的契约书', '魔神王の契約書', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只恶魔族融合怪兽融合召唤。「DD」融合怪兽融合召唤的场合，也能把自己墓地的怪兽除外作为融合素材。 ②：自己准备阶段发动。自己受到1000伤害。'),
(9765723, 'Dark Contract with the Witch', '女武神的契约书', '戦乙女の契約書', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「女武神的契约书」的①的效果1回合只能使用1次。 ①：从手卡把1张「DD」卡或者「契约书」卡送去墓地，以场上1张卡为对象才能发动。那张卡破坏。 ②：只要这张卡在魔法与陷阱区域存在，自己场上的恶魔族怪兽的攻击力在对方回合内上升1000。 ③：自己准备阶段发动。自己受到1000伤害。'),
(45974017, 'Dark Contract with the Yamimakai', '暗魔界的契约书', '闇魔界の契約書', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「暗魔界的契约书」的①的效果1回合只能使用1次。 ①：从以下效果选择1个才能把这个效果发动。 ●以自己墓地1只「DD」灵摆怪兽为对象才能发动。那只怪兽在自己的灵摆区域放置。 ●从自己的额外卡组把1只表侧表示的「DD」灵摆怪兽在自己的灵摆区域放置。 ②：自己准备阶段发动。自己受到1000伤害。'),
(32665564, 'Dark Contract with the Zero King', '零王的契约书', '零王の契約書', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「DD」卡使用。这个卡名的①的效果1回合只能使用1次。 ①：以「零王的契约书」以外的自己场上1张「DD」卡为对象才能发动。那张卡破坏，从卡组把1只「DD」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是「DD」怪兽不能特殊召唤。 ②：自己准备阶段发动。自己受到1000伤害。'),
(70231910, 'Dark Core', '黑核', 'ブラック・コア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡。将场上1只表侧表示的怪兽从游戏中除外。'),
(98696958, 'Dark Corridor', '暗黑回廊', '暗黒回廊', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「暗黑界」怪兽加入手卡。那之后，选自己1张手卡丢弃。'),
(300302061, 'Dark Creation', NULL, NULL, 'Skill Card', 'Yubel', NULL, NULL, NULL, NULL, NULL),
(91596726, 'Dark Crusader', '暗黑十字军', 'ダーク・クルセイダー', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 200, '可以从手卡把1只暗属性怪兽送去墓地，这张卡的攻击力上升400。'),
(3701074, 'Dark Cure', '暗黑治疗', 'ダーク・キュア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方把怪兽召唤·反转召唤·特殊召唤时，对方回复那些怪兽的攻击力一半数值的基本分。'),
(65824822, 'Dark Deal', '暗之取引', '闇の取引', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的通常魔法发动时支付1000基本分才能发动。那个时候对方发动的通常魔法的效果变成「对方随机把手卡丢弃1张」。'),
(70187958, 'Dark Desertapir', '暗黑沙貘', 'ダーク砂バク', 'Effect Monster', 'Beast', 'EARTH', 2, 1100, 300, '这张卡从游戏中除外时，可以选择自己墓地存在的1只4星以下的兽族怪兽特殊召唤。'),
(78053598, 'Dark Designator', '暗之指名者', '闇の指名者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '宣言1种怪兽卡的名字。当这种怪兽卡在对方的卡组中存在时，那种卡其中1张加入对方手卡。'),
(109401, 'Dark Dimension Soldier', '暗次元的兵士', '闇次元の戦士', 'Synchro Monster', 'Warrior', 'DARK', 5, 1200, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：把1张手卡除外，以除外的1只自己的暗属性怪兽为对象才能发动。那只怪兽表侧守备表示或者里侧守备表示特殊召唤。 ②：自己·对方的结束阶段发动。给与对方为场上盖放的卡数量×100伤害。'),
(31919988, 'Dark Diviner', '漆黑之朱姆沃尔特', '漆黒のズムウォルト', 'Synchro Monster', 'Fiend', 'DARK', 4, 2000, 1000, '暗属性调整＋调整以外的昆虫族怪兽1只 这张卡不会被战斗破坏。这张卡的攻击宣言时，攻击对象怪兽的攻击力比这张卡的攻击力高的场合，攻击对象怪兽的攻击力直到战斗阶段结束时变成和这张卡相同数值。这张卡战斗破坏对方怪兽送去墓地时，从对方卡组上面把3张卡送去墓地。'),
(62312469, 'Dark Doriado', '黑暗多里雅德', 'ダーク・ドリアード', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 1400, '①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组选地·水·炎·风属性怪兽各1只用喜欢的顺序回到卡组上面。'),
(18803791, 'Dark Dragon Ritual', '黑龙降临', '黒竜降臨', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「黑龙之圣骑士」的降临必需。 ①：从自己的手卡·场上把等级合计直到4以上的怪兽解放，从手卡把「黑龙之圣骑士」仪式召唤。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把1张「真红眼」魔法·陷阱卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(65287621, 'Dark Driceratops', '暗黑三角怪鸟龙', '暗黒ドリケラトプス', 'Effect Monster', 'Dinosaur', 'EARTH', 6, 2400, 1500, '这张卡攻击守备表示的怪兽时，攻击力超出部分对对方造成战斗伤害。'),
(89111398, 'Dark Dust Spirit', '沙尘之恶灵', '砂塵の悪霊', 'Spirit Monster', 'Zombie', 'EARTH', 6, 2200, 1800, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到主人的手卡。这张卡召唤·反转时，场上的这张卡以外的全部表侧表示的怪兽破坏。'),
(81755371, 'Dark Effigy', '暗构体', 'ダークフレーム', 'Effect Monster', 'Fiend', 'DARK', 4, 1500, NULL, '暗属性的通常怪兽祭品召唤的场合，这1只怪兽可以作为2只的数量的祭品。'),
(53194323, 'Dark Element', '黑暗元素', 'ダーク・エレメント', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己墓地有「门之守护神」怪兽存在的场合，把基本分支付一半才能发动。从手卡·卡组·额外卡组把1只11星以上的「门之守护神」怪兽无视召唤条件特殊召唤。 ②：把墓地的这张卡除外才能发动。自己的卡组·除外状态的「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」的其中1只加入手卡。'),
(21417692, 'Dark Elf', '暗精灵', 'ダーク・エルフ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 2000, 800, '这张卡不支付1000基本分不能攻击。'),
(88643579, 'Dark End Dragon', '暗黑终结龙', 'ダークエンド・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 8, 2600, 2100, '调整＋调整以外的暗属性怪兽1只以上 1回合1次，可以把这张卡的攻击力·守备力下降500，对方场上存在的1只怪兽送去墓地。'),
(62002838, 'Dark End Evaporation Dragon', '暗与消灭之龙', '闇と消滅の竜', 'Effect Monster', 'Dragon', 'DARK', 8, 2600, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：从额外卡组把1只龙族·8星怪兽除外才能发动。这张卡从手卡特殊召唤。这个回合，自己不是龙族怪兽不能特殊召唤。 ②：可以从以下效果选择1个发动。 ●自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。 ●以场上1只其他的攻击表示怪兽为对象才能发动。这张卡的攻击力·守备力下降500，作为对象的怪兽破坏。'),
(4614116, 'Dark Energy', '暗能量', '闇・エネルギー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '恶魔族怪兽才能装备。 ①：装备怪兽的攻击力·守备力上升300。'),
(29436665, 'Dark Eradicator Warlock', '黑之执行官', '黒魔導の執行官', 'Effect Monster', 'Spellcaster', 'DARK', 7, 2500, 2100, '这张卡不能通常召唤。把自己场上存在的1只「黑魔术师」解放的场合才能特殊召唤。只要这张卡在场上表侧表示存在，每次自己或者对方把通常魔法卡发动，给与对方基本分1000分伤害。'),
(674561, 'Dark Eruption', '暗黑爆发', 'ダーク・バースト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只攻击力1500以下的暗属性怪兽为对象才能发动。那只暗属性怪兽加入手卡。'),
(88685329, 'Dark Eye Nightmare', '暗眼梦魇', 'ダークアイ・ナイトメア', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, 1700, '这个卡名的①的效果1回合只能使用1次。 ①：把自己墓地最多3张陷阱卡除外才能发动。除外数量的以下效果适用。 ●1张：自己从卡组抽1张，那之后选1张手卡回到卡组最上面。 ●2张：自己从卡组抽1张。 ●3张：自己从卡组抽2张，那之后选1张手卡丢弃。 ②：1回合1次，这张卡被战斗破坏的场合，可以作为代替把自己墓地1张陷阱卡除外。'),
(90928333, 'Dark Factory of Mass Production', '暗之量产工厂', '闇の量産工場', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只通常怪兽为对象才能发动。那些怪兽加入手卡。'),
(9064354, 'Dark Factory of More Production', '暗之增产工厂', '闇の増産工場', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：把自己的手卡·场上1只怪兽送去墓地才能发动。自己从卡组抽1张。'),
(13722870, 'Dark Flare Knight', '黑炎之骑士', '黒炎の騎士－ブラック・フレア・ナイト－', 'Fusion Monster', 'Warrior', 'DARK', 6, 2200, 800, '「黑魔术师」＋「炎之剑士」 ①：这张卡的战斗发生的对自己的战斗伤害变成0。 ②：这张卡被战斗破坏送去墓地的场合发动。从手卡·卡组把1只「幻影之骑士」特殊召唤。'),
(94979322, 'Dark Flare Swordsman', '黑炎之剑士', '黒炎の剣士－ブラック・フレア・ソードマン－', 'Effect Monster', 'Warrior', 'FIRE', 6, 2200, 800, '这个卡名的①③的效果1回合各能使用1次。 ①：把1只「炎之剑士」或者有那个卡名记述的怪兽从额外卡组送去墓地才能发动。这张卡从手卡特殊召唤。这个回合，自己不用战士族怪兽不能攻击宣言。 ②：这张卡的战斗发生的对自己的战斗伤害变成0。 ③：自己·对方回合，把这张卡解放才能发动。把6星以外的有「炎之剑士」的卡名记述的1只怪兽从卡组特殊召唤。'),
(67904682, 'Dark Flattop', '暗黑航空母舰', 'ダーク・フラット・トップ', 'Synchro Monster', 'Machine', 'DARK', 8, NULL, 3000, '暗属性调整＋调整以外的机械族怪兽1只以上 1回合1次，选择自己墓地1只名字带有「反应机」的怪兽或者「巨人轰炸机·大空袭式」才能发动。选择的怪兽无视召唤条件特殊召唤。此外，这张卡被破坏送去墓地的场合，可以从手卡把1只5星以下的机械族怪兽特殊召唤。'),
(94820406, 'Dark Fusion', '黑暗结合', 'ダーク・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的手卡·场上的怪兽作为融合素材，把1只恶魔族融合怪兽融合召唤。这个回合，对方不能把这个效果特殊召唤的怪兽作为效果的对象。'),
(41114306, 'Dark Garnex the Cubic Beast', '方界兽 暗黑之甘尼克斯', '方界獣ダーク・ガネックス', 'Effect Monster', 'Beast', 'EARTH', 2, NULL, NULL, '这张卡不能通常召唤。把自己场上1只「方界」怪兽送去墓地的场合可以特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力上升1000。 ②：这张卡战斗破坏怪兽时，以自己墓地最多2只「方界胤 毗贾姆」为对象才能发动。这张卡送去墓地，作为对象的怪兽特殊召唤。那之后，可以从卡组把1只「方界兽 利刃之迦楼迪亚」加入手卡。'),
(70676581, 'Dark General Freed', '暗黑将军 弗里德', 'ダーク・ジェネラル フリード', 'Effect Monster', 'Warrior', 'DARK', 5, 2300, 1700, '这张卡不能特殊召唤。自己场上表侧表示存在的暗属性怪兽为对象的魔法卡的效果无效并破坏。只要这张卡在场上表侧表示存在，可以作为自己的抽卡阶段时进行通常抽卡的代替，从自己卡组把1只4星的暗属性怪兽加入手卡。'),
(9159938, 'Dark Gray', '暗黑灰羚', 'ダーク・グレイ', 'Normal Monster', 'Beast', 'EARTH', 3, 800, 900, '全身灰色的野兽，是非常少见的珍贵品种。'),
(14536035, 'Dark Grepher', '暗黑古雷法', 'ダーク・グレファー', 'Effect Monster', 'Warrior', 'DARK', 4, 1700, 1600, '①：这张卡可以从手卡丢弃1只5星以上的暗属性怪兽，从手卡特殊召唤。 ②：1回合1次，从手卡丢弃1只暗属性怪兽才能发动。从卡组把1只暗属性怪兽送去墓地。'),
(26746975, 'Dark Guardian', '暗之守护神－黑暗守护者', '闇の守護神－ダーク・ガーディアン', 'Effect Monster', 'Warrior', 'DARK', 12, 3800, 3800, '这个卡名在规则上也当作「门之守护神」卡使用。这张卡不能通常召唤，用「暗元素」的效果以及以下方法才能特殊召唤。 ●可以让自己的手卡·场上（表侧表示）·墓地·除外状态的「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」各1张回到卡组，从手卡·墓地特殊召唤。 ①：这张卡不会被战斗破坏。 ②：「暗元素」的效果特殊召唤的这张卡不受其他怪兽以及对方发动的魔法卡的效果影响。'),
(75326861, 'Dark Highlander', '天刑王 黑天', '天刑王 ブラック・ハイランダー', 'Synchro Monster', 'Fiend', 'DARK', 7, 2800, 2300, '恶魔族调整＋调整以外的恶魔族怪兽1只以上 只要这张卡在场上表侧表示存在，双方不能同调召唤。1回合1次，选择有装备卡装备的1只对方怪兽才能发动。选择的怪兽装备的装备卡全部破坏，给与对方基本分破坏数量×400的数值的伤害。'),
(53129443, 'Dark Hole', '黑洞', 'ブラック・ホール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的怪兽全部破坏。'),
(72880377, 'Dark Hole Dragon', '黑洞龙', 'ブラック・ホール・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，场上的怪兽被不以自身为对象的卡的效果破坏的场合才能发动。这张卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。这个回合的结束阶段，从卡组把1张「黑洞」加入手卡。 ③：场上的这张卡不会被效果破坏。'),
(26914168, 'Dark Honest', '暗黑奥尼斯特', 'ダーク・オネスト', 'Effect Monster', 'Fairy', 'DARK', 4, 1100, 1900, '①：1回合1次，自己主要阶段才能发动。场上的表侧表示的这张卡回到持有者手卡。 ②：自己的暗属性怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只对方怪兽的攻击力直到回合结束时下降那自身攻击力数值。'),
(16964437, 'Dark Horizon', '暗黑边界', 'ダーク・ホライズン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己因战斗·效果受到伤害时才能发动。把持有受到的伤害数值以下的攻击力的1只魔法师族·暗属性怪兽从卡组特殊召唤。'),
(66214679, 'Dark Horus', '暗黑荷鲁斯龙', 'ダーク・ホルス・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, 1800, '只要这张卡在场上表侧表示存在，对方的主要阶段时魔法卡发动的场合，可以选择自己墓地1只4星的暗属性怪兽特殊召唤。这个效果1回合只能使用1次。'),
(19357125, 'Dark Hunter', '暗黑暗杀者', 'ダーク・アサシン', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 400, '自己墓地存在的暗属性怪兽数量让这张卡得到以下效果。 ●1张以下：这张卡的攻击力下降400。 ●2至4张：这张卡的攻击力上升400。 ●5张以上：可以把这张卡送去墓地，对方场上里侧表示存在的怪兽全部破坏。'),
(5562461, 'Dark Illusion', '暗之幻影', '闇の幻影', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '场上表侧表示存在的暗属性怪兽为对象的效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。'),
(74567889, 'Dark Infant @Ignister', '暗婴＠伊格尼斯者', 'ダークインファント＠イグニスター', 'Link Monster', 'Cyberse', 'DARK', NULL, 500, NULL, '连接怪兽以外的「@火灵天星」怪兽1只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1张「火灵天星“艾”心乐园岛」加入手卡。 ②：原本攻击力是2300的电子界族怪兽把效果发动时才能发动。这张卡的位置向作为这张卡所连接区的自己的主要怪兽区域移动。那之后，可以把这张卡的属性直到回合结束时变更为任意属性。'),
(90980792, 'Dark Jeroid', '暗黑胶体人', 'ダークジェロイド', 'Effect Monster', 'Fiend', 'DARK', 4, 1200, 1500, '这张卡召唤·反转召唤·特殊召唤成功时，选择场上1只表侧表示怪兽。只要那只怪兽在场上表侧表示存在，攻击力下降800。'),
(53375573, 'Dark King of the Abyss', '深渊冥王', '深淵の冥王', 'Normal Monster', 'Fiend', 'DARK', 3, 1200, 800, '冥界之王，听说以前有着支配所有黑暗力量的能力。'),
(85313220, 'Dark Lucius LV4', '漆黑之魔王 LV4', '漆黒の魔王 LV４', 'Effect Monster', 'Fiend', 'EARTH', 4, 1000, 300, '这张卡战斗破坏的对方怪兽的效果无效化。这张卡战斗破坏怪兽的下次的自己回合的准备阶段时，可以把这张卡送去墓地从手卡·卡组特殊召唤1只「漆黑之魔王 LV6」。'),
(12817939, 'Dark Lucius LV6', '漆黑之魔王 LV6', '漆黒の魔王 LV６', 'Effect Monster', 'Fiend', 'EARTH', 6, 1700, 600, '用「漆黑之魔王 LV4」的效果特殊召唤的场合，这张卡战斗破坏的对方怪兽的效果无效化。这个效果把对方怪兽的效果无效化的下次的自己回合的准备阶段时，可以把这张卡送去墓地从手卡·卡组特殊召唤1只「漆黑之魔王 LV8」。'),
(58206034, 'Dark Lucius LV8', '漆黑之魔王 LV8', '漆黒の魔王 LV８', 'Effect Monster', 'Fiend', 'EARTH', 8, 2800, 900, '用「漆黑之魔王 LV6」的效果特殊召唤的场合，这张卡战斗破坏的对方怪兽的效果无效化，并且从游戏中除外。'),
(71440209, 'Dark Magic Amulet', '黑魔术之护符', '黒魔術の護符', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡也能把手卡1只魔法师族怪兽给对方观看，在盖放的回合发动。 ①：连锁有「黑魔术师」的卡名记述的卡的效果的发动让怪兽的效果发动时才能发动。那个效果无效，这个回合，原本卡名和那只怪兽相同的怪兽发动的效果无效化。 ②：这张卡在墓地存在的状态，自己把「黑魔术师」特殊召唤的场合，支付2500基本分才能发动。这张卡在自己场上盖放。'),
(2314238, 'Dark Magic Attack', '黑・魔・导', '黒・魔・導', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「黑魔术师」存在的场合才能发动。对方场上的魔法·陷阱卡全部破坏。'),
(99789342, 'Dark Magic Curtain', '黑魔术的幕帘', '黒魔術のカーテン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽召唤·反转召唤·特殊召唤。 ①：把基本分支付一半才能发动。从卡组把1只「黑魔术师」特殊召唤。'),
(111280, 'Dark Magic Expanded', '黑魔导强化', '黒魔導強化', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：双方的场上·墓地的「黑魔术师」「黑魔术少女」数量的以下效果适用。 ●1只以上：选场上1只魔法师族·暗属性怪兽，那个攻击力直到回合结束时上升1000。 ●2只以上：这个回合，对方不能对应自己的魔法·陷阱卡的效果的发动把魔法·陷阱·怪兽的效果发动，自己场上的魔法·陷阱卡不会被对方的效果破坏。 ●3只以上：自己场上的魔法师族·暗属性怪兽直到回合结束时不受对方的效果影响。'),
(41735184, 'Dark Magic Inheritance', '黑魔术之继承', '黒魔術の継承', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地把2张魔法卡除外才能发动。把「黑魔术的继承」以外的有「黑魔术师」的卡名或者「黑魔术少女」的卡名记述的1张魔法·陷阱卡从卡组加入手卡。'),
(59016454, 'Dark Magic Mirror Force', '黑魔术防护罩－反射镜力－', '黒魔術のバリア －ミラーフォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时或者有要让场上的怪兽破坏的对方怪兽的效果发动时，若有着有「光之黄金柜」的卡名记述的怪兽在场上存在则能发动。对方场上的攻击表示怪兽全部破坏。自己场上有「黑魔术师」存在的场合，再给与对方破坏的怪兽数量×500伤害。这张卡的发动后，这个回合中，有「光之黄金柜」的卡名记述的自己场上的怪兽各有1次不会被战斗·效果破坏。'),
(70168345, 'Dark Magic Twin Burst', '黑·魔·导·连·弹', '黒・魔・導・連・弾', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「黑魔术师」为对象才能发动。那只怪兽的攻击力直到回合结束时上升双方的场上·墓地的「黑魔术少女」的攻击力的合计数值。'),
(82404868, 'Dark Magic Veil', '黑魔术的帷幕', '黒魔術のヴェール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付1000基本分才能发动。从自己的手卡·墓地选1只魔法师族·暗属性怪兽特殊召唤。'),
(47222536, 'Dark Magical Circle', '黑之魔导阵', '黒の魔導陣', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：作为这张卡的发动时的效果处理，从自己卡组上面把3张卡确认。可以从那之中把1只「黑魔术师」或者1张有那个卡名记述的魔法·陷阱卡给对方观看并加入手卡。剩下的卡用喜欢的顺序回到卡组上面。 ②：自己场上有「黑魔术师」召唤·特殊召唤的场合，以对方场上1张卡为对象才能发动。那张卡除外。'),
(46986414, 'Dark Magician', '黑魔导', 'ブラック・マジシャン', 'Normal Monster', 'Spellcaster', 'DARK', 7, 2500, 2100, '作为魔法师，攻击力·守备力都是最高级别。'),
(38033121, 'Dark Magician Girl', '黑魔导女孩', 'ブラック・マジシャン・ガール', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2000, 1700, '①：这张卡的攻击力上升双方墓地的「黑魔术师」「黑混沌之魔术师」数量×300。'),
(43892408, 'Dark Magician Girl the Dragon Knight', '龙骑士黑魔导女孩', '竜騎士ブラック・マジシャン・ガール', 'Fusion Monster', 'Dragon', 'DARK', 7, 2600, 1700, '「黑魔术少女」＋龙族怪兽 这张卡用以上记的卡为融合素材的融合召唤以及用「蒂迈欧之眼」的效果才能特殊召唤。 ①：自己·对方回合1次，把1张手卡送去墓地，以场上1张表侧表示卡为对象才能发动。那张表侧表示卡破坏。'),
(2501624, 'Dark Magician Girl the Magician''s Apprentice', '魔术师的弟子－黑魔导女孩', '魔術師の弟子－ブラック・マジシャン・ガール', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2000, 1700, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以丢弃1张手卡，从手卡特殊召唤。这个方法特殊召唤的这张卡的卡名当作「黑魔术少女」使用。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「光之黄金柜」加入手卡。 ③：这张卡的攻击力上升有「光之黄金柜」的卡名记述的双方墓地的怪兽数量×300。'),
(50725996, 'Dark Magician Knight', '黑魔术骑士', 'ブラック・マジシャンズ・ナイト', 'Effect Monster', 'Warrior', 'DARK', 7, 2500, 2100, '这张卡不能通常召唤。「骑士的称号」的效果才能特殊召唤。 ①：这张卡特殊召唤成功的场合，以场上1张卡为对象发动。那张卡破坏。'),
(40737112, 'Dark Magician of Chaos', '混沌黑魔术师', '混沌の黒魔術師', 'Effect Monster', 'Spellcaster', 'DARK', 8, 2800, 2600, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的回合的结束阶段，以自己墓地1张魔法卡为对象才能发动。那张卡加入手卡。 ②：这张卡战斗破坏对方怪兽的伤害计算后发动。那只对方怪兽除外。 ③：表侧表示的这张卡从场上离开的场合除外。'),
(59400890, 'Dark Magician of Destruction', '毁灭的黑魔术师', '滅びの黒魔術師', 'Fusion Monster', 'Spellcaster', 'DARK', 8, 2800, 2600, '「黑魔术师」＋光·暗属性怪兽 「毁灭之黑魔术师」1回合1次用融合召唤以及以下方法才能特殊召唤。 ●魔法卡的效果发动的回合，把自己场上1只6星以上的魔法师族·暗属性怪兽除外的场合可以从额外卡组特殊召唤。 ①：这张卡的卡名只要在场上·墓地存在当作「黑魔术师」使用。 ②：这张卡特殊召唤的场合才能发动。把1只「黑魔术师」或者1张有那个卡名记述的卡从卡组加入手卡。'),
(41721210, 'Dark Magician the Dragon Knight', '龙骑士黑魔导', '竜騎士ブラック・マジシャン', 'Fusion Monster', 'Dragon', 'DARK', 8, 3000, 2500, '「黑魔术师」＋龙族怪兽 ①：这张卡的卡名只要在场上·墓地存在当作「黑魔术师」使用。 ②：只要这张卡在怪兽区域存在，自己场上的魔法·陷阱卡不会被对方的效果破坏，对方不能把那些作为效果的对象。'),
(5829717, 'Dark Magician the Knight of Dragon Magic', '龙魔导骑士黑魔导', '竜魔導騎士ブラック・マジシャン', 'Fusion Monster', 'Dragon', 'DARK', 8, 2900, 2400, '「黑魔术师」＋7星以上的龙族·战士族怪兽 ①：自己怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：1回合1次，自己怪兽战斗破坏对方怪兽时才能发动。给与对方那只破坏的怪兽的原本攻击力数值的伤害。 ③：这张卡被破坏的场合才能发动。「黑魔术师」「龙骑士 盖亚」各1只从自己的手卡·卡组·额外卡组·墓地选出特殊召唤。'),
(342673, 'Dark Magician the Magician of Black Magic', '黑色魔术师－黑魔导', '黒き魔術師－ブラック・マジシャン', 'Effect Monster', 'Spellcaster', 'DARK', 7, 2500, 2100, '这个卡名的①③的效果1回合各能使用1次。 ①：场上有「光之黄金柜」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡只要在怪兽区域存在，卡名当作「黑魔术师」使用。 ③：这张卡被效果破坏的场合，若场上有5星以上的怪兽存在则能发动。这张卡特殊召唤。那之后，可以从卡组把有「黑魔术师」的卡名记述的1张魔法·陷阱卡在自己场上盖放。'),
(41722932, 'Dark Mambele', '暗黑灭绝切割', 'ダーク・ジェノサイド・カッター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有暗属性怪兽3只以上存在的场合才能发动。选择场上表侧表示存在的1张卡从游戏中除外。'),
(97642679, 'Dark Master - Zorc', '暗之支配者-佐克', '闇の支配者－ゾーク', 'Ritual Effect Monster', 'Fiend', 'DARK', 8, 2700, 1500, '「与暗之支配者的契约」降临。 ①：1回合1次，自己主要阶段才能发动。掷1次骰子，出现的数目的效果适用。 ●1·2：对方场上的怪兽全部破坏。 ●3·4·5：选对方场上1只怪兽破坏。 ●6：自己场上的怪兽全部破坏。'),
(74713516, 'Dark Mimic LV1', '暗黑之宝箱怪 LV1', '暗黒のミミック LV１', 'Flip Effect Monster', 'Fiend', 'DARK', 1, 100, 1000, '反转：从卡组抽1张卡。此外，自己的准备阶段时，可以把表侧表示的这张卡送去墓地，从手卡·卡组特殊召唤1只「暗黑之宝箱怪 LV3」'),
(1102515, 'Dark Mimic LV3', '暗黑之宝箱怪 LV3', '暗黒のミミック LV３', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1000, '这张卡因为战斗送去墓地的场合，这张卡的控制者从卡组抽1张卡。这张卡因为「暗黑之宝箱怪 LV1」的效果特殊召唤的场合改成抽2张卡。'),
(20522190, 'Dark Mirror Force', '邪恶防护罩 -暗黑之力-', '邪悪なるバリア －ダーク・フォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。对方场上守备表示存在的怪兽全部从游戏中除外。'),
(31829185, 'Dark Necrofear', '暗黑人偶 妮可罗菲娅', 'ダーク・ネクロフィア', 'Effect Monster', 'Fiend', 'DARK', 8, 2200, 2800, '这张卡不能通常召唤。从自己墓地把3只恶魔族怪兽除外的场合可以特殊召唤。 ①：怪兽区域的这张卡被对方破坏送去墓地的回合的结束阶段，以对方场上1只表侧表示怪兽为对象发动。墓地的这张卡当作装备卡使用给那只对方怪兽装备。 ②：这张卡的效果让这张卡装备中的场合，得到装备怪兽的控制权。'),
(21960890, 'Dark Necromancer', '大尸教', '大屍教', 'Effect Monster', 'Zombie', 'DARK', 4, 1000, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从手卡·卡组把1只恶魔族·不死族的仪式怪兽送去墓地。那之后，可以从卡组把1张仪式魔法卡加入手卡。 ②：这张卡被除外的场合，以自己的除外状态的1只4星以下的恶魔族·不死族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(38107923, 'Dark Nephthys', '暗黑奈芙提斯', 'ダーク・ネフティス', 'Effect Monster', 'Winged Beast', 'DARK', 8, 2400, 1600, '自己的主要阶段时自己墓地的暗属性怪兽是3只以上的场合，可以通过把那之内2只从游戏中除外，这张卡从手卡送去墓地。下次的自己的准备阶段时，这个效果送去墓地的这张卡从墓地特殊召唤。此外，这张卡特殊召唤成功时，选择场上1张魔法·陷阱卡破坏。'),
(98502113, 'Dark Paladin', '超魔导剑士-黑魔导剑士', '超魔導剣士－ブラック・パラディン', 'Fusion Monster', 'Spellcaster', 'DARK', 8, 2900, 2400, '「黑魔术师」＋「破坏之剑士」 这张卡不用融合召唤不能特殊召唤。 ①：这张卡的攻击力上升双方的场上·墓地的龙族怪兽数量×500。 ②：魔法卡发动时，丢弃1张手卡才能发动。这张卡在怪兽区域表侧表示存在的场合，那个发动无效并破坏。'),
(13193642, 'Dark Plant', '暗黑植物', 'ダーク・プラント', 'Normal Monster', 'Plant', 'DARK', 1, 300, 400, '在被污染的土地以及暗之力的环境下生长的花。非常凶暴。'),
(89558090, 'Dark Prisoner', '暗黑囚犯', 'ダーク・プリズナー', 'Normal Monster', 'Fiend', 'DARK', 3, 600, 1000, '能巧妙的操纵光的反射来隐藏自己。'),
(99261403, 'Dark Rabbit', '暗黑兔', 'ダーク・ラビット', 'Normal Monster', 'Beast', 'DARK', 4, 1100, 1500, '美国卡通世界里面的兔子罗杰。经常敏捷而匆忙的行动。'),
(16195942, 'Dark Rebellion Xyz Dragon', '暗反叛超量龙', 'ダーク・リベリオン・エクシーズ・ドラゴン', 'XYZ Monster', 'Dragon', 'DARK', 4, 2500, 2000, '4星怪兽×2 ①：把这张卡2个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成一半，这张卡的攻击力上升那个数值。'),
(45462639, 'Dark Red Enchanter', '暗红之魔导师', '闇紅の魔導師', 'Effect Monster', 'Spellcaster', 'DARK', 6, 1700, 2200, '这张卡召唤成功时，这张卡放置2个魔力指示物。只要这张卡在场上表侧表示存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。这张卡放置的魔力指示物每有1个，这张卡的攻击力上升300。1回合1次，可以把这张卡放置的2个魔力指示物取除，对方手卡随机丢弃1张。'),
(9287078, 'Dark Renewal', '黑魔族复活之棺', '黒魔族復活の棺', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方对怪兽的召唤·特殊召唤成功时，以那1只怪兽和自己场上1只魔法师族怪兽为对象才能发动。那2只怪兽送去墓地。那之后，可以从自己的卡组·墓地选1只魔法师族·暗属性怪兽特殊召唤。'),
(1621413, 'Dark Requiem Xyz Dragon', '暗镇魂超量龙', 'ダーク・レクイエム・エクシーズ・ドラゴン', 'XYZ Monster', 'Dragon', 'DARK', 5, 3000, 2500, '5星怪兽×3 ①：这张卡有「暗叛逆超量龙」在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0，这张卡的攻击力上升那个原本攻击力数值。 ●对方把怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。那之后，可以选自己墓地1只超量怪兽特殊召唤。'),
(97021916, 'Dark Resonator', '暗黑共鸣者', 'ダーク・リゾネーター', 'Tuner Monster', 'Fiend', 'DARK', 3, 1300, 300, '①：这张卡1回合只有1次不会被战斗破坏。'),
(85562745, 'Dark Room of Nightmare', '噩梦之拷问室', '悪夢の拷問部屋', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次「噩梦之拷问室」以外的卡的效果让对方受到伤害发动。给与对方300伤害。'),
(90724272, 'Dark Rose Fairy', '暗蔷薇之妖精', '闇薔薇の妖精', 'Effect Monster', 'Fairy', 'DARK', 2, 800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：调整特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡在墓地存在的场合，把自己的手卡·场上1张卡送去墓地才能发动。这张卡回到卡组最上面或者最下面。'),
(53982768, 'Dark Ruler Ha Des', '冥界的魔王 哈·迪斯', '冥界の魔王 ハ・デス', 'Effect Monster', 'Fiend', 'DARK', 6, 2450, 1600, '这张卡不能作从墓地的特殊召唤。 ①：只要这张卡在怪兽区域存在，自己的恶魔族怪兽战斗破坏怪兽的场合，那破坏的怪兽只要在场上·墓地存在效果无效化。'),
(54693926, 'Dark Ruler No More', '冥王结界波', '冥王結界波', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '不能对应这张卡的发动让怪兽的效果发动。 ①：对方场上的全部表侧表示怪兽的效果直到回合结束时无效。这张卡的发动后，直到回合结束时对方受到的全部伤害变成0。'),
(76045757, 'Dark Sacrifice', '替罪的黑暗', '身代わりの闇', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：要让场上的卡破坏的魔法·陷阱·怪兽的效果由对方发动时才能发动。那个效果无效。那之后，从卡组把1只3星以下的暗属性怪兽送去墓地。'),
(92377303, 'Dark Sage', '黑衣大贤者', '黒衣の大賢者', 'Effect Monster', 'Spellcaster', 'DARK', 9, 2800, 3200, '这张卡不能通常召唤。猜中自己的「时间魔术师」的掷硬币效果时，可以把自己场上存在的1只「黑魔术师」解放从手卡或者卡组中特殊召唤。这个方法特殊召唤成功时，从自己卡组把1张魔法卡加入手卡。'),
(16625614, 'Dark Sanctuary', '暗黑圣域', 'ダーク・サンクチュアリ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己的「通灵盘」的效果要让「死之信息」卡出现的场合，可以让那卡作为通常怪兽（恶魔族·暗·1星·攻/守0）特殊召唤。这个效果特殊召唤的卡不受「通灵盘」以外的卡的效果影响，不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。 ②：对方怪兽的攻击宣言时发动。进行1次投掷硬币。表的场合，那次攻击无效，给与对方那只对方怪兽的攻击力一半数值的伤害。'),
(69402394, 'Dark Scheme', '暗黑的谋略', '暗黒の謀略', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '双方玩家选择2张手卡丢弃，从卡组抽2张卡。对方可以丢弃1张手卡让这张卡的效果无效。'),
(61587183, 'Dark Scorpion - Chick the Yellow', '黑蝎-飞速逃跑的齐克', '黒蠍－逃げ足のチック', 'Effect Monster', 'Warrior', 'DARK', 3, 1000, 1000, '这张卡对对方造成战斗伤害时，从下列效果中选择1项发动： ●将场上1张卡弹回持有者手卡。 ●检视对方卡组最上面1张卡（对方不能确认这张卡），并选择将其放回对方卡组最上面或最下面。'),
(6967870, 'Dark Scorpion - Cliff the Trap Remover', '黑蝎-拆除陷阱的克里夫', '黒蠍－罠はずしのクリフ', 'Effect Monster', 'Warrior', 'DARK', 3, 1200, 1000, '①：这张卡给与对方战斗伤害时，可以从以下效果选择1个发动。 ●以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ●从对方卡组上面把2张卡送去墓地。');